+  for (absl::string_view path :
+       {"$.a..", "$...*", "$.foo*", "$.*[-1]", "$.*[-0]", "$.*[1_2]",
+        "$.a..[-1]", "$.a..[-0]", "$.a..[1_2]", "lax $.*", "lax $[*]",
+        "lax $..a", "lax recursive $.*", "lax recursive $..a"}) {
