+      {"$[*]", R"(["foo"])", R"([[]])"},
+      {"$..a", R"({"a": "foo"})", R"({"a": []})"},
+      {"$.b..*", R"({"b": {"c": "foo"}})", R"({"b": {"c": []}})"},
+      {"$..[*]", R"({"d": ["foo"]})", R"([[]])"},
+  };
